_PIECES: list[tuple[re.Pattern[str], str]] = []


def _pieces() -> list[tuple[re.Pattern[str], str]]:
    """Each English piece of a call (a report, a question, an answer) as a pattern, with its key: the longest first."""
    if not _PIECES:
        english = {"ask": ASK, "ask_ground": ASK_GROUND, "unanswered": UNANSWERED, "still": STILL}
        for kind in KINDS:
            for severity, words in PLAYS[kind]["report"].items():
                english[f"{kind}.report.{severity}"] = words
            for part in PARTS:
                english[f"{kind}.{part}"] = PLAYS[kind][part]
        made = [(re.escape(w).replace(re.escape("{row}"), r"(?P<row>\w+)"), k) for k, w in english.items()]
        made.append((SORTED, "sorted"))
        _PIECES.extend((re.compile(p), k) for p, k in sorted(made, key=lambda x: -len(x[0])))
    return _PIECES


def in_language(text: str, code: str) -> str | None:
    """A whole call about a problem on board in language ``code``; None when it can't all be put into it."""
    table = WORDS.get(code)
    if not table:
        return None
    out, at = [], 0
    while at < len(text):
        if text[at].isspace():
            at += 1
            continue
        for pattern, key in _pieces():
            if (m := pattern.match(text, at)) is not None and key in table:
                out.append(table[key].format(row=m.groupdict().get("row") or ""))
                at = m.end()
                break
        else:
            return None
        if key == "still":  # ("Still as I said, Captain: the report": the report without its "Captain, ")
            rest = text[at:].strip()
            for pattern, k in _pieces():
                if k.startswith(KINDS) and ".report." in k and (m := pattern.fullmatch("Captain, " + rest)):
                    report = table[k].format(row=m.groupdict().get("row") or "")
                    out.append(re.sub(r"^[^,，:]{1,12}[,，]\s*", "", report, count=1))  # (its "Captain," said once)
                    at = len(text)
                    break
            else:
                return None
    return ("" if code == "zh" else " ").join(out) if out else None
